import { runScript } from '../../sdk/runner';

await runScript(async ({ bot, sdk }) => {
  const log = (...a: any[]) => console.log('[fight]', ...a);
  const st0 = sdk.getState();
  log('start at', st0?.player.worldX, st0?.player.worldZ, 'hp', st0?.player.hp);

  const eq = async (re: RegExp) => {
    try { const r = await bot.equipItem(re); log('equip', String(re), r.success); } catch (e) { log('equip err', String(e)); }
  };
  await eq(/^bronze sword$/i);
  await eq(/^wooden shield$/i);

  const STATE = () => sdk.getState();

  async function killPatterns(pats: RegExp[], ms: number) {
    const end = Date.now() + ms;
    let kills = 0;
    const lastNames = new Set<string>();
    while (Date.now() < end) {
      const st = STATE();
      if (!st) { await new Promise(r => setTimeout(r, 300)); continue; }
      if ((st.player.hp ?? 10) < 4) {
        const eaten = await bot.eatFood().catch(() => null as any);
        log('ate', eaten?.success);
      }
      let target: any = null;
      for (const p of pats) {
        const c = st.nearbyNpcs
          .filter(n => p.test(n.name) && n.reachable !== false && n.optionsWithIndex.some(o => /attack/i.test(o.text)))
          .sort((a, b) => (a.hp ?? 99) - (b.hp ?? 99) || a.distance - b.distance)[0];
        if (c) { target = c; break; }
      }
      if (!target) {
        // wander a bit toward fallback waypoint
        await new Promise(r => setTimeout(r, 500));
        continue;
      }
      const res = await bot.attack(target, 6000).catch((e: any) => ({ success: false, reason: String(e) }));
      if (!res.success) { log('attack fail', target.name, target.combatLevel, res.reason); await new Promise(r => setTimeout(r, 500)); continue; }
      // wait until combat ends (kill or target fled)
      try { await sdk.waitForCondition((s: any) => !s.player.combat.inCombat, 25000); } catch {}
      kills++;
      lastNames.add(target.name);
      const stx = STATE();
      log('fight done, hp', stx?.player.hp, 'kills~', kills);
    }
    return { kills, lastNames: [...lastNames] };
  }

  // go to goblin cluster
  let st = STATE();
  const d = Math.hypot(st.player.worldX - 3252, st.player.worldZ - 3230);
  if (d > 12) { const r = await bot.walkTo(3252, 3230, 4, { timeout: 60000 }); log('walk goblins', r.success, r.message); }
  const g = await killPatterns([/^goblin$/i], 90000);
  log('goblin result', JSON.stringify(g));

  // cows field (open gate if needed)
  st = STATE();
  log('at', st.player.worldX, st.player.worldZ);
  const gate = sdk.findNearbyLoc(/^gate$/i);
  if (gate) { await bot.openDoor(gate).catch(() => {}); }
  const w = await bot.walkTo(3253, 3290, 6, { timeout: 70000 }).catch((e: any) => ({ success: false, message: String(e) }));
  log('walk cows', w.success, (w as any).message);
  const c = await killPatterns([/^cow$/i], 90000);
  log('cow result', JSON.stringify(c));

  const fin = STATE();
  log('END skill atk', sdk.getSkillXp('attack'), 'str', sdk.getSkillXp('strength'), 'hp', fin?.player.hp);
}, { timeout: 300_000 });
